static int eq12(const uint64_t a[12], const uint64_t b[12]) {
    for (int i = 0; i < 12; i++)
        if (a[i] != b[i])
            return 0;
    return 1;
}

int main(void) {
    TEST_SUITE("p256_point_add_affine");

    for (int i = 0; i < NMADD; i++) {
        uint64_t out[12];
        p256_point_add_affine(out, VECS[i].p1, VECS[i].aff);
        ASSERT_EQ("Jacobian + affine matches reference", 1,
                  eq12(out, VECS[i].want));
    }

    // out aliasing p1 must work: mul_base adds into its accumulator
    // in place.
    {
        uint64_t buf[12];
        for (int i = 0; i < 12; i++)
            buf[i] = VECS[0].p1[i];
        p256_point_add_affine(buf, buf, VECS[0].aff);
        ASSERT_EQ("out aliasing p1 matches reference", 1,
                  eq12(buf, VECS[0].want));
    }

    test_summary();
    return 0;
}
